package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Snapshot;

/** A person just transferred from one sheet to another, by whom, and the other sheet's figures as
 *  they were before the person arrived. */
public record Transfer(String name, String from, String to, String user, Snapshot toBefore) {
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumbers;
import net.officefloor.hq.app.claim.Claims;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;

/** Moving a person from their sheet to another. */
@Service
public class Transfers {

    private final JdbcTemplate jdbc;
    private final Claims claims;
    private final ClaimNumbers numbers;

    public Transfers(JdbcTemplate jdbc, Claims claims, ClaimNumbers numbers) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.numbers = numbers;
    }

    /** Transfer the person to sheet `to`, answering their id there. They arrive with every grade they
     *  were given (and its from-date), their terms, contact and aliases, and their claims (listed in
     *  the order they were) with their status, dates, notes, tags, frozen figures, logs and comments;
     *  each claim that had a number takes the other sheet's next one, in the order the claims were
     *  opened (by the sheet's today when each was opened, then by the order they were added). Figures
     *  a statement bound are lost, the statement count starts at 0, and references, locks and settle
     *  batches are not carried. The person then leaves their sheet entirely: with their claims go
     *  their statements, holds, watches, patron links (either way), pool memberships and period totals. */
    public long transfer(Person person, String to) {
        long fromId = person.getId();
        long toId = insertPerson(person, to);

        List<Claim> kept = new ArrayList<>(claims.ofPerson(person.getSheetId(), fromId));
        Collections.reverse(kept); // oldest listed first, so they keep their order
        Map<Long, String> renumbered = renumber(kept, to);
        for (Claim claim : kept) {
            long newId = insertClaim(claim, to, toId, renumbered.get(claim.getId()));
            jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) "
                    + "SELECT ?, ?, status, by_user, on_date, due FROM claim_log WHERE claim_id = ? ORDER BY id",
                    to, newId, claim.getId());
            jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, on_date, comment_text) "
                    + "SELECT ?, ?, by_user, on_date, comment_text FROM claim_comment WHERE claim_id = ? ORDER BY id",
                    to, newId, claim.getId());
        }

        for (Claim claim : kept) {
            jdbc.update("DELETE FROM claim_log WHERE claim_id = ?", claim.getId());
            jdbc.update("DELETE FROM claim_comment WHERE claim_id = ?", claim.getId());
            jdbc.update("DELETE FROM claim WHERE id = ?", claim.getId());
        }
        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", fromId, fromId);
        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", fromId);
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", person.getSheetId(), fromId);
        for (String table : List.of("person_alias", "person_statement", "person_hold", "person_watch", "person_grade")) {
            jdbc.update("DELETE FROM " + table + " WHERE person_id = ?", fromId);
        }
        jdbc.update("DELETE FROM person WHERE id = ?", fromId);
        return toId;
    }

    private long insertPerson(Person person, String to) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade, terms, contact, position) VALUES (?, ?, ?, ?, ?, "
                            + People.END_POSITION + ")", new String[] { "id" });
            ps.setString(1, to);
            ps.setString(2, person.getName());
            ps.setString(3, person.getFirstGrade());
            ps.setObject(4, person.getTerms(), java.sql.Types.INTEGER);
            ps.setString(5, person.getContact());
            ps.setString(6, to);
            return ps;
        }, keys);
        long toId = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) "
                + "SELECT ?, ?, grade, from_date FROM person_grade WHERE person_id = ? ORDER BY id",
                to, toId, person.getId());
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, alias_key) "
                + "SELECT ?, ?, alias, alias_key FROM person_alias WHERE person_id = ? ORDER BY id",
                to, toId, person.getId());
        return toId;
    }

    /** The new number on sheet `to` of each claim that had one, by its id, given in the order opened. */
    private Map<Long, String> renumber(List<Claim> kept, String to) {
        Map<Long, LocalDate> openedOn = new HashMap<>();
        for (Claim claim : kept) {
            if (claim.getNumber() == null) continue;
            List<Date> dates = jdbc.queryForList(
                    "SELECT on_date FROM claim_log WHERE claim_id = ? AND status = 'OPEN' ORDER BY id",
                    Date.class, claim.getId());
            openedOn.put(claim.getId(), dates.isEmpty() ? claim.getDate() : dates.get(0).toLocalDate());
        }
        List<Claim> numbered = kept.stream().filter(c -> c.getNumber() != null)
                .sorted(Comparator.comparing((Claim c) -> openedOn.get(c.getId())).thenComparing(Claim::getId))
                .toList();
        Map<Long, String> renumbered = new HashMap<>();
        for (Claim claim : numbered) {
            Claim there = new Claim(null, to, 0, claim.getAmount(), claim.getDate(), claim.getNote(),
                    claim.getStatus(), null, claim.getDue(), claim.getOpenedBy());
            there.setDueBy(claim.getDueBy());
            renumbered.put(claim.getId(), numbers.next(there));
        }
        return renumbered;
    }

    private long insertClaim(Claim claim, String to, long toId, String number) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement("INSERT INTO claim (sheet_id, person_id, amount, claim_date, "
                    + "note, status, number, due, opened_by, stated, stated_due, corrects, due_by, deferred_until, "
                    + "proofs, split_from, locked_by, late_entry, reminded_on, ref, tags, tags_used, void_reason, "
                    + "edited_by, due_terms, batch) SELECT ?, ?, amount, claim_date, note, status, ?, due, opened_by, "
                    + "FALSE, NULL, corrects, due_by, deferred_until, proofs, split_from, NULL, late_entry, reminded_on, "
                    + "NULL, tags, tags_used, void_reason, edited_by, due_terms, NULL FROM claim WHERE id = ?",
                    new String[] { "id" });
            ps.setString(1, to);
            ps.setLong(2, toId);
            ps.setString(3, number);
            ps.setLong(4, claim.getId());
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** A steward transfers the person to another sheet (see {@link Transfers#transfer}). Refused: anyone
 *  but a steward, a retired person, this sheet's own id, an archived sheet, and a name, alias or
 *  contact of the person already on the other sheet. Publishes the person as they arrived. */
public class TransferPerson {
    public void transfer(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            @Val TransferRequest request, People people, Transfers transfers, Settings settings, Sheets sheets,
            Rollup rollup, Out<Person> personOut, Out<Transfer> transferOut)
            throws PersonNotFoundException, InvalidSheetRequestException {
        String to = request.to().trim();
        if (settings.role(sheetId, request.user()) != Role.STEWARD) {
            throw new InvalidSheetRequestException("Only a steward can transfer people");
        }
        if (to.equals(sheetId)) {
            throw new InvalidSheetRequestException("A person cannot be transferred to their own sheet");
        }
        Person person = people.lock(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        if (person.isRetired()) {
            throw new InvalidSheetRequestException("A retired person cannot be transferred");
        }
        if (sheets.archived(to)) {
            throw new InvalidSheetRequestException("The other sheet is archived");
        }
        if (people.nameTaken(to, person.getName(), null)
                || person.getAliases().stream().anyMatch(alias -> people.nameOrAliasTaken(to, alias))
                || (person.getContact() != null && people.contactTaken(to, person.getContact(), null))) {
            throw new InvalidSheetRequestException("The other sheet already has this name, alias or contact");
        }
        Snapshot toBefore = rollup.snapshot(to);
        long arrivedId = transfers.transfer(person, to);
        personOut.set(people.find(to, arrivedId));
        transferOut.set(new Transfer(person.getName(), sheetId, to, request.user(), toBefore));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the transfer is saved, so a refused one writes no audit line: this sheet's line. */
public class RecordPersonTransferred {
    public void record(@Val Transfer transfer, Audit audit) {
        audit.record("PERSON_TRANSFERRED sheet=" + transfer.from() + " by=" + transfer.user()
                + " name=" + transfer.name() + " to=" + transfer.to());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;

/** The other sheet's lines of a transfer: the person arrived, then the figures it moved there. */
public class RecordPersonArrived {
    public void record(@Val Transfer transfer, Audit audit, Rollup rollup) {
        audit.record("PERSON_TRANSFERRED sheet=" + transfer.to() + " by=" + transfer.user()
                + " name=" + transfer.name() + " from=" + transfer.from());
        rollup.record(transfer.to(), transfer.toBefore(), transfer.user());
    }
}
package net.officefloor.hq.app;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class RespondWithAuditLines {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "name", required = false) String name, Audit audit,
            ObjectResponse<List<String>> response) {
        response.send(audit.linesFor(sheetId, name));
    }
}
# A steward transfers the person to another sheet by its id: they arrive there with their grades,
# terms, contact, aliases and claims (renumbered there), and leave this sheet entirely. Refused (400)
# for anyone else, a retired person, this sheet's own id, or a name, alias or contact already there.
validate:
  class: net.officefloor.hq.app.person.ValidateTransfer
  next: snapshot
# Keep this sheet's figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: record
# Audit only once the transfer is saved: this sheet's line, then its rollup lines.
record:
  class: net.officefloor.hq.app.person.RecordPersonTransferred
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: arrived
# The other sheet's line, then its rollup lines.
arrived:
  class: net.officefloor.hq.app.person.RecordPersonArrived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# The sheet's audit lines as the audit file holds them, newest first; with ?name= only the lines
# about that person (name= or person=, compared as names are). Reads the file; records nothing.
respond:
  class: net.officefloor.hq.app.RespondWithAuditLines
